#include "extension_form_files.h"
#include <iostream>
using namespace moon::extension;using namespace winrt::Windows::Data::Json;
void check(bool b,const char* m){if(!b)throw std::runtime_error(m);}
int main(int argc,char** argv){winrt::init_apartment();try{const auto root=std::filesystem::absolute(std::filesystem::path(argv[1]))/("files-"+std::to_string(GetCurrentProcessId())+"-"+std::to_string(GetTickCount64()));std::filesystem::create_directories(root);std::ofstream(root/L"动画.PNG",std::ios::binary)<<"png";std::ofstream(root/"cat.mspet",std::ios::binary)<<"pet";
 auto select=[&](OPENFILENAMEW* dialog){check(bool(dialog->Flags&OFN_ALLOWMULTISELECT)&&bool(dialog->Flags&OFN_NOCHANGEDIR),"native multi chooser flags");auto put=[&](const std::wstring& part){std::copy(part.begin(),part.end(),dialog->lpstrFile);dialog->lpstrFile+=part.size();*dialog->lpstrFile++=0;};put(root.wstring());put(L"动画.PNG");put(L"cat.mspet");*dialog->lpstrFile=0;return TRUE;};const auto target=root/"saved.mspet";int saveCount=0;auto save=[&](OPENFILENAMEW* dialog){++saveCount;check(std::wstring(dialog->lpstrFile)==L"cat.mspet"&&std::wstring(dialog->lpstrDefExt)==L"mspet"&&(dialog->Flags&OFN_OVERWRITEPROMPT),"save defaults");wcscpy_s(dialog->lpstrFile,dialog->nMaxFile,target.c_str());return TRUE;};FormFiles files(nullptr,select,save);auto input=files.choose(JsonObject{});check(input&&input->size()==2&&(*input)[0].name==L"动画.PNG"&&(*input)[0].mime==L"image/png"&&(*input)[0].bytes==std::vector<std::uint8_t>{'p','n','g'}&&(*input)[1].mime.empty(),"multi read and MIME");check(files.save((*input)[1])&&saveCount==1&&std::filesystem::file_size(target)==3,"atomic save actual file");
 FormFiles cancelled(nullptr,[](auto*){return FALSE;},[](auto*){return FALSE;});check(!cancelled.choose(JsonObject{})&&!cancelled.save((*input)[1]),"cancel no result");auto reject=[&](auto fn){bool failed=false;try{fn();}catch(...){failed=true;}check(failed,"expected rejection");};for(const auto& name:{L"../bad.mspet",L"bad.",L"bad.a-b",L"bad.abcdefghijklmnopq"})reject([&]{files.save({name,L"",{1}});});check(saveCount==1,"invalid export showed chooser");
 const auto large=root/"large.png";{std::ofstream file(large,std::ios::binary);file.seekp(16*1024*1024);file.put('x');}FormFiles oversized(nullptr,[&](auto* dialog){wcscpy_s(dialog->lpstrFile,dialog->nMaxFile,large.c_str());return TRUE;});reject([&]{oversized.choose(JsonObject{});});FormFiles missing(nullptr,[&](auto* dialog){auto path=root/"missing.png";wcscpy_s(dialog->lpstrFile,dialog->nMaxFile,path.c_str());return TRUE;});reject([&]{missing.choose(JsonObject{});});
 FormState state;JsonObject view;view.Insert(L"nodes",JsonArray::Parse(LR"([{"id":"export","type":"button"}])"));state.receive(view,0);auto request=*state.click(L"export");JsonObject result;result.Insert(L"requestId",request.GetNamedValue(L"requestId"));result.Insert(L"file",JsonObject::Parse(LR"({"name":"cat.mspet","bytes":[7,8,9,0]})"));view.Insert(L"result",result);state.receive(view,0,[&](const auto& f){return files.save(f);});check(saveCount==2&&std::filesystem::file_size(target)==4&&!state.busy(),"matched response actual save");state.receive(view,0,[&](const auto& f){return files.save(f);});check(saveCount==2,"disk replay prevented");std::cout<<"Native chooser multi-read/cancel/limits/name gates/atomic save/form replay passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}catch(const winrt::hresult_error& e){std::cerr<<winrt::to_string(e.message())<<'\n';return 1;}}
